/* Thin harvest outlines and a bounded, shared sparkle pool. */
(()=>{'use strict';const T=THREE,P=EmberWorld.prototype,edgeCache=new WeakMap(),edgeMaterial=new T.LineBasicMaterial({color:'#ffffff',transparent:true,opacity:.28,depthWrite:false});
const oldResource=P.resource,oldLoot=P.lootVisual,oldUpdate=P.update;
P.resource=function(...args){const r=oldResource.apply(this,args);r.outlines=[];const meshes=[];r.mesh.traverse(o=>{if(o.isMesh)meshes.push(o);});for(const mesh of meshes){let edges=edgeCache.get(mesh.geometry);if(!edges){edges=new T.EdgesGeometry(mesh.geometry,40);edgeCache.set(mesh.geometry,edges);}const line=new T.LineSegments(edges,edgeMaterial);line.scale.setScalar(1.015);line.visible=false;mesh.add(line);r.outlines.push(line);}return r;};
P.lootVisual=function(...args){const g=oldLoot.apply(this,args),box=new T.Box3().setFromObject(g),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()).sub(g.position);const geometry=new T.EdgesGeometry(new T.BoxGeometry(Math.max(.5,size.x+.08),Math.max(.45,size.y+.08),Math.max(.4,size.z+.08))),line=new T.LineSegments(geometry,edgeMaterial);line.position.copy(center);line.userData.pickupFrame=true;line.userData.transientGeometry=true;g.add(line);return g;};
P.update=function(t,state,env){oldUpdate.call(this,t,state,env);for(const r of this.resources){const show=Math.hypot(r.x-state.x,r.z-state.z)<14&&Math.abs(r.y-state.y)<5&&!(state.depleted[r.id]>t);for(const line of r.outlines||[])line.visible=show;}for(const g of this.dynamic.children){const line=g.children.find(c=>c.userData.pickupFrame);if(line)line.visible=Math.hypot(g.position.x-state.x,g.position.z-state.z)<14;}};
P.pickupBurst=function(x,y,z){if(!this.pickupPool){const positions=new Float32Array(96*3),colors=new Float32Array(96*3),geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(positions,3));geometry.setAttribute('color',new T.BufferAttribute(colors,3));const c=document.createElement('canvas');c.width=c.height=32;const ctx=c.getContext('2d'),gradient=ctx.createRadialGradient(16,16,1,16,16,16);gradient.addColorStop(0,'white');gradient.addColorStop(.25,'#ffffffdd');gradient.addColorStop(1,'#ffffff00');ctx.fillStyle=gradient;ctx.fillRect(0,0,32,32);const material=new T.PointsMaterial({map:new T.CanvasTexture(c),size:.14,vertexColors:true,transparent:true,depthWrite:false,blending:T.AdditiveBlending});const mesh=new T.Points(geometry,material);mesh.frustumCulled=false;this.dynamic.add(mesh);this.pickupPool={mesh,positions,colors,life:new Float32Array(96),velocity:new Float32Array(96*3),next:0};for(let n=0;n<96;n++)positions[n*3+1]=-5000;}
const p=this.pickupPool;for(let n=0;n<18;n++){const i=p.next++%96,a=n*2.399,power=.35+n%4*.15;p.life[i]=.65+(n%5)*.06;p.positions.set([x+Math.cos(a)*.18,y,z+Math.sin(a)*.18],i*3);p.velocity.set([Math.cos(a)*power,1+n%3*.3,Math.sin(a)*power],i*3);}};
P.updatePickups=function(dt){const p=this.pickupPool;if(!p)return;for(let i=0;i<96;i++){if(p.life[i]<=0)continue;p.life[i]-=dt;const f=Math.max(0,p.life[i]/.85);for(let axis=0;axis<3;axis++)p.positions[i*3+axis]+=p.velocity[i*3+axis]*dt;p.colors.set([f*.75,f,f*.81],i*3);if(p.life[i]<=0)p.positions[i*3+1]=-5000;}p.mesh.geometry.attributes.position.needsUpdate=true;p.mesh.geometry.attributes.color.needsUpdate=true;};
})();
